pub fn parse_port_argument(input: &str) -> i32 {
    match parse_stoi_i32(input) {
        Some(value) => value,
        None => std::process::abort(),
    }
}

fn parse_stoi_i32(input: &str) -> Option<i32> {
    let trimmed = input.trim_start_matches(|c: char| c.is_whitespace());
    let bytes = trimmed.as_bytes();

    if bytes.is_empty() {
        return None;
    }

    let mut index = 0usize;
    let mut negative = false;

    match bytes[0] {
        b'+' => index = 1,
        b'-' => {
            negative = true;
            index = 1;
        }
        _ => {}
    }

    let digits_start = index;
    let mut value = 0i64;

    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        value = value.checked_mul(10)?;
        value = value.checked_add(i64::from(byte - b'0'))?;
        index += 1;
    }

    if index == digits_start {
        return None;
    }

    let signed_value = if negative { -value } else { value };
    i32::try_from(signed_value).ok()
}

