use super::path::normalize_path;

pub struct URL {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    pub fn from_components(
        scheme: String,
        host: String,
        port: i32,
        path: String,
        query: String,
        fragment: String,
    ) -> Self {
        Self {
            scheme,
            host,
            port,
            path: normalize_path(path),
            query,
            fragment,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn to_string(&self) -> String {
        let mut rendered = String::new();

        if self.scheme.is_empty() {
            rendered.push_str(&self.path);
        } else {
            rendered.push_str(&self.scheme);
            rendered.push_str("://");
            rendered.push_str(&self.host);

            if self.port >= 0 {
                rendered.push(':');
                rendered.push_str(&self.port.to_string());
            }

            rendered.push_str(&self.path);
        }

        if !self.query.is_empty() {
            rendered.push('?');
            rendered.push_str(&self.query);
        }

        if !self.fragment.is_empty() {
            rendered.push('#');
            rendered.push_str(&self.fragment);
        }

        rendered
    }

    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }
}

