pub fn normalize_path(path: String) -> String {
    if path.is_empty() || path.starts_with('/') {
        return path;
    }

    let mut normalized = String::with_capacity(path.len() + 1);
    normalized.push('/');
    normalized.push_str(&path);
    normalized
}

