mod output_lib;

use output_lib::cli::parse_port_argument;
use output_lib::url_parser::URL;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 7 {
        std::process::exit(1);
    }

    let scheme = args[1].clone();
    let host = args[2].clone();
    let port = parse_port_argument(&args[3]);
    let path = args[4].clone();
    let query = args[5].clone();
    let fragment = args[6].clone();

    let parser = URL::from_components(scheme, host, port, path, query, fragment);

    println!("{}", parser.scheme());
    println!("{}", parser.host());
    println!("{}", parser.port());
    println!("{}", parser.path());
    println!("{}", parser.query());
    println!("{}", parser.fragment());
    println!("{}", parser.to_string());
    println!("{}", if parser.is_valid() { 1 } else { 0 });
}
